INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine einseitige Verzweigung dasselbe wie eine zweiseitige Verzweigung?', 2, '[{"text": "Nein", "correct": true, "because": "Nur ein Pfad vs. zwei"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Strukturen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat eine einseitige Verzweigung?', 3, '[{"text": "Bedingte Ausführung eines Codeblocks", "correct": true, "because": "Nur bei Erfüllung"}, {"text": "Zwei Alternativen prüfen", "correct": false, "because": "Zweiseitig"}, {"text": "Schleifen ausführen", "correct": false, "because": "Andere Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine einseitige Verzweigung?', 5, '[{"text": "Eine Bedingung", "correct": true, "because": "Entscheidungsgrundlage"}, {"text": "Ein Ausführungspfad", "correct": true, "because": "Nur bei True"}, {"text": "Zwei Ausführungspfade", "correct": false, "because": "Zweiseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine einseitige Verzweigung hat keinen Else-Zweig. b) Sie wird immer ausgeführt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bedingungsabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer einseitigen Verzweigung?', 4, '[{"text": "Bedingung", "correct": false, "because": "Entscheidend"}, {"text": "Codeblock", "correct": false, "because": "Ausführungsteil"}, {"text": "Farbschema", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine einseitige Verzweigung mehrere Bedingungen haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "Mit AND/OR kombinierbar"}, {"text": "Nein", "correct": false, "because": "Flexibel kombinierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur ist eine einseitige Verzweigung?', 3, '[{"text": "If ohne Else", "correct": true, "because": "Einseitig"}, {"text": "If-Else", "correct": false, "because": "Zweiseitig"}, {"text": "While-Schleife", "correct": false, "because": "Wiederholung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine einseitige Verzweigung?', 5, '[{"text": "Einfachheit", "correct": true, "because": "Ein Pfad"}, {"text": "Klarheit", "correct": true, "because": "Übersichtlich"}, {"text": "Zwei Alternativen", "correct": false, "because": "Nur ein Pfad"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine einseitige Verzweigung hat eine Bedingung. b) Sie führt immer zwei Codeblöcke aus. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur ein Block"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine einseitige Verzweigung?', 4, '[{"text": "Bedingung", "correct": false, "because": "Entscheidungsgrundlage"}, {"text": "Codeblock", "correct": false, "because": "Ausführungsteil"}, {"text": "Else-Zweig", "correct": true, "because": "Einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine einseitige Verzweigung immer zweiseitig erweiterbar?', 2, '[{"text": "Ja", "correct": true, "because": "Else hinzufügbar"}, {"text": "Nein", "correct": false, "because": "Erweiterbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprachen nutzen einseitige Verzweigungen?', 4, '[{"text": "Python", "correct": true, "because": "if ohne else"}, {"text": "Java", "correct": true, "because": "if ohne else"}, {"text": "HTML", "correct": false, "because": "Keine Programmierlogik"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine einseitige Verzweigung nur für komplexe Programme ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Logik"}, {"text": "Ja", "correct": false, "because": "Grundstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer einseitigen Verzweigung?', 3, '[{"text": "Klare Bedingung", "correct": true, "because": "Entscheidung treffen"}, {"text": "Zwei Pfade", "correct": false, "because": "Einseitig"}, {"text": "Farben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine einseitige Verzweigung hat einen Pfad. b) Sie enthält immer Schleifen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schleifen separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Darstellungen zeigen eine einseitige Verzweigung?', 5, '[{"text": "Struktogramm", "correct": true, "because": "If ohne Else"}, {"text": "Flussdiagramm", "correct": true, "because": "Ein Pfad"}, {"text": "UML-Klassendiagramm", "correct": false, "because": "Statische Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer einseitigen Verzweigung unwichtig?', 3, '[{"text": "Bedingung", "correct": false, "because": "Entscheidend"}, {"text": "Ausführungspfad", "correct": false, "because": "Kernmerkmal"}, {"text": "Zweiter Pfad", "correct": true, "because": "Einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine einseitige Verzweigung verschachtelt sein?', 3, '[{"text": "Ja", "correct": true, "because": "If in If möglich"}, {"text": "Nein", "correct": false, "because": "Verschachtelung erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine einseitige Verzweigung immer ausgeführt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Bedingungsabhängig"}, {"text": "Ja", "correct": false, "because": "Nur bei True"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für eine einseitige Verzweigung zentral?', 4, '[{"text": "Bedingung", "correct": true, "because": "Entscheidungsgrundlage"}, {"text": "Zwei Pfade", "correct": false, "because": "Zweiseitig"}, {"text": "Schleifenstruktur", "correct": false, "because": "Andere Logik"}]');
